#!/usr/bin/env python3
"""Generate a self-contained, interactive report from the isolated matrix."""
import argparse, json, statistics, html, csv
from pathlib import Path
NAMES={'idle-500':'Library · 500 tracks','idle-5000':'Library · 5,000 tracks','idle-20000':'Library · 20,000 tracks','artwork-idle':'Library · 64 distinct covers','scroll':'Track scrolling','artwork-scroll':'Scrolling · 64 covers','search':'Compact search · scrolling','search-filter':'Compact search · filtered “005”','drawer':'Navigation drawer · GPU blur','settings':'Settings dialog · GPU blur','fullscreen':'Fullscreen · paused ambient','fullscreen-playing':'Fullscreen · synthetic beat profile','minimized':'Minimized · paused library'}
def median(v):return statistics.median(v) if v else None
def percentile(v,p):return sorted(v)[round((len(v)-1)*p)] if v else None
def summarize(run):
    out={k:run[k] for k in ('app','scenario','run','tracks','artwork','rss_mib_median','rss_mib_max','cpu_percent_one_core','startup_detect_ms','elapsed_seconds')}
    out['process_count']=median([s['process_count'] for s in run['samples']]);out['opening_ms']=run['ready'].get('opening_callback_ms')
    m=run.get('metrics') or {};times=m.get('times_ms')
    if times:intervals=[b-a for a,b in zip(times,times[1:])];out['frame_kind']='WebView rAF callbacks'
    else:
        times=sorted(m.get('presented_seconds',[]));intervals=[1000*(b-a) for a,b in zip(times,times[1:])];out['frame_kind']='Metal actual presentations'
    out['diagnostic_fps']=1000/statistics.mean(intervals) if len(intervals)>10 else None
    out['p95_interval_ms']=percentile(intervals,.95) if len(intervals)>10 else None
    out['p99_interval_ms']=percentile(intervals,.99) if len(intervals)>10 else None
    out['diagnostic_frames']=len(times or []);out['cpu_draw_p50_ms']=median(m.get('cpu_draw_ms',[]));out['cpu_draw_p95_ms']=percentile(m.get('cpu_draw_ms',[]),.95)
    pairs=sorted(zip(m.get('presented_seconds',[]),m.get('scene_signatures',[])));changed=[t for i,(t,s) in enumerate(pairs) if i==0 or pairs[i-1][1]!=s]
    out['changed_glyph_scenes_per_second']=(len(changed)-1)/(changed[-1]-changed[0]) if len(changed)>10 and run['scenario'] in ('scroll','artwork-scroll','search') else None
    return out
